package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;
/** Separate study notebook, keyed by URI, segment and extracted source digest. */
final class ReaderStore extends SQLiteOpenHelper {
 final Context app;final long epoch=WorkspaceEpoch.value;void current(){if(epoch!=WorkspaceEpoch.value||WorkspaceEpoch.restoring)throw new IllegalStateException("O caderno foi recuperado. Reabra esta janela.");}
 ReaderStore(Context c){super(c,"seeky-reader.db",null,2);app=c.getApplicationContext();}
 static void contentChanged(Context c){SharedPreferences p=c.getSharedPreferences("reading_tools",0);synchronized(p){p.edit().putBoolean("index_dirty",true).putLong("index_revision",System.currentTimeMillis()).putLong("speech_text_revision",p.getLong("speech_text_revision",0)+1).apply();}}
 void dirty(){contentChanged(app);try{StudyState.bump(app);}catch(Exception e){AppDiagnostics.record(app,"notebook-backup-state",e);app.getSharedPreferences("seeky",0).edit().putString("notebook_warning","O caderno foi guardado, mas o estado de backup precisa de revisão.").apply();}}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE draft(uri TEXT, segment INTEGER, digest TEXT, value TEXT, marks TEXT, PRIMARY KEY(uri,segment,digest))");d.execSQL("CREATE TABLE bookmark(id INTEGER PRIMARY KEY,uri TEXT,segment INTEGER,position INTEGER,label TEXT,created INTEGER)");journalSchema(d);}
 public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<2){try{NotebookBackup.recovery(app,d,"before-reader-v2.json");}catch(Exception e){throw new SQLiteException("Não foi possível criar a cópia anterior do caderno. A migração foi cancelada: "+e.getClass().getSimpleName());}journalSchema(d);app.getSharedPreferences("seeky",0).edit().putBoolean("notebook_migration_notice",true).apply();}}
 static String digest(String value){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 StudyText load(String uri,int segment,String source){StudyText result=new StudyText(source);try(Cursor c=getReadableDatabase().rawQuery("SELECT value,marks FROM draft WHERE uri=? AND segment=? AND digest=?",new String[]{uri,""+segment,digest(source)})){if(c.moveToFirst()){result=new StudyText(c.getString(0));JSONArray a=new JSONArray(c.getString(1));for(int i=0;i<a.length();i++){JSONObject m=a.getJSONObject(i);int s=m.getInt("s"),e=m.getInt("e");if(s>=0&&e>=s&&e<=result.text.length())result.marks.add(new StudyText.Mark(s,e,m.getString("k"),m.optString("n")));}}}catch(JSONException e){throw new IllegalStateException("Anotações inválidas.",e);}return result;}
 static void journalSchema(SQLiteDatabase d){d.execSQL("CREATE TABLE edit_history(id INTEGER PRIMARY KEY,uri TEXT NOT NULL,segment INTEGER NOT NULL,digest TEXT NOT NULL,before_value TEXT NOT NULL,before_marks TEXT NOT NULL,after_value TEXT NOT NULL,after_marks TEXT NOT NULL,label TEXT NOT NULL,created INTEGER NOT NULL,undone INTEGER NOT NULL DEFAULT 0 CHECK(undone IN (0,1)))");d.execSQL("CREATE INDEX edit_part ON edit_history(uri,segment,digest,id)");d.execSQL("CREATE TABLE cut_clip(id INTEGER PRIMARY KEY,uri TEXT NOT NULL,segment INTEGER NOT NULL,value TEXT NOT NULL,created INTEGER NOT NULL)");}
 static String marks(StudyText value){JSONArray rows=new JSONArray();try{for(StudyText.Mark m:value.marks)rows.put(new JSONObject().put("s",m.start).put("e",m.end).put("k",m.kind).put("n",m.note));return rows.toString();}catch(JSONException e){throw new IllegalStateException(e);}}
 static boolean same(StudyText a,StudyText b){return a.text.equals(b.text)&&marks(a).equals(marks(b));}
 static StudyText decode(String text,String marks){try{if(marks.length()>8388608)throw new IllegalArgumentException("Anotações acima de 8 milhões de caracteres.");JsonBudget.check(marks,8,2000);StudyText value=new StudyText(text);JSONArray rows=new JSONArray(marks);if(text.length()>1048576||rows.length()>1000)throw new IllegalArgumentException("Caderno acima do limite.");for(int i=0;i<rows.length();i++){JSONObject m=rows.getJSONObject(i);int start=m.getInt("s"),end=m.getInt("e");String kind=m.getString("k"),note=m.optString("n");if(start<0||end<start||end>text.length()||!Arrays.asList("highlight","highlight-green","highlight-blue","highlight-pink","highlight-orange","highlight-purple","underline","strike","note").contains(kind)||note.length()>20000)throw new IllegalArgumentException("Anotação inválida.");value.marks.add(new StudyText.Mark(start,end,kind,note));}return value;}catch(JSONException e){throw new IllegalArgumentException("Caderno inválido.",e);}}
 void writeDraft(SQLiteDatabase db,String uri,int segment,String digest,StudyText value){ContentValues v=new ContentValues();v.put("uri",uri);v.put("segment",segment);v.put("digest",digest);v.put("value",value.text);v.put("marks",marks(value));if(db.insertWithOnConflict("draft",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new IllegalStateException("Não foi possível guardar o caderno.");}
 void save(String uri,int segment,String source,StudyText value){saveEdit(uri,segment,source,load(uri,segment,source),value,"Editar caderno",null);}
 void saveEdit(String uri,int segment,String source,StudyText before,StudyText after,String label,String clip){current();
  decode(after.text,marks(after));if(same(before,after))return;String hash=digest(source),bm=marks(before),am=marks(after);
  long bytes=(long)before.text.getBytes(StandardCharsets.UTF_8).length+bm.getBytes(StandardCharsets.UTF_8).length+after.text.getBytes(StandardCharsets.UTF_8).length+am.getBytes(StandardCharsets.UTF_8).length;
  if(bytes>4194304)throw new IllegalStateException("Esta alteração excede o limite de 4 MB do histórico. Exporte o caderno antes de continuar.");
  SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{
   if(!same(load(uri,segment,source),before))throw new IllegalStateException("O caderno foi alterado noutra janela. Reabra esta parte antes de editar.");
   db.delete("edit_history","uri=? AND segment=? AND digest=? AND undone=1",new String[]{uri,""+segment,hash});
   ContentValues v=new ContentValues();v.put("uri",uri);v.put("segment",segment);v.put("digest",hash);v.put("before_value",before.text);v.put("before_marks",bm);v.put("after_value",after.text);v.put("after_marks",am);v.put("label",label);v.put("created",System.currentTimeMillis());db.insertOrThrow("edit_history",null,v);
   if(clip!=null){if(clip.length()>1048576)throw new IllegalArgumentException("Texto cortado acima do limite.");ContentValues c=new ContentValues();c.put("uri",uri);c.put("segment",segment);c.put("value",clip);c.put("created",System.currentTimeMillis());db.insertOrThrow("cut_clip",null,c);}
   writeDraft(db,uri,segment,hash,after);trimJournal(db,uri,segment,hash);db.setTransactionSuccessful();
  }finally{db.endTransaction();}dirty();
 }
 static long journalBytes(SQLiteDatabase db,String clause,String[] args){try(Cursor c=db.rawQuery("SELECT COALESCE(SUM(length(CAST(before_value AS BLOB))+length(CAST(before_marks AS BLOB))+length(CAST(after_value AS BLOB))+length(CAST(after_marks AS BLOB))),0) FROM edit_history"+clause,args)){c.moveToFirst();return c.getLong(0);}}
 static void trimJournal(SQLiteDatabase db,String uri,int part,String digest){String[] args={uri,""+part,digest};db.execSQL("DELETE FROM edit_history WHERE uri=? AND segment=? AND digest=? AND id NOT IN (SELECT id FROM edit_history WHERE uri=? AND segment=? AND digest=? ORDER BY id DESC LIMIT 20)",new Object[]{uri,part,digest,uri,part,digest});while(journalBytes(db," WHERE uri=? AND segment=? AND digest=?",args)>8388608)db.execSQL("DELETE FROM edit_history WHERE id=(SELECT MIN(id) FROM edit_history WHERE uri=? AND segment=? AND digest=?)",new Object[]{uri,part,digest});while(journalBytes(db,"",null)>67108864)db.execSQL("DELETE FROM edit_history WHERE id=(SELECT MIN(id) FROM edit_history)");db.execSQL("DELETE FROM cut_clip WHERE id NOT IN (SELECT id FROM cut_clip ORDER BY id DESC LIMIT 20)");try(Cursor c=db.rawQuery("SELECT COALESCE(SUM(length(CAST(value AS BLOB))),0) FROM cut_clip",null)){c.moveToFirst();if(c.getLong(0)>8388608)db.execSQL("DELETE FROM cut_clip WHERE id NOT IN (SELECT id FROM cut_clip ORDER BY id DESC LIMIT 1)");}}
 StudyText travel(String uri,int part,String source,StudyText expected,boolean redo){current();SQLiteDatabase db=getWritableDatabase();String hash=digest(source);StudyText result;db.beginTransaction();try{
  if(!same(load(uri,part,source),expected))throw new IllegalStateException("O caderno mudou. Reabra esta parte antes de desfazer.");
  try(Cursor c=db.rawQuery("SELECT id,before_value,before_marks,after_value,after_marks FROM edit_history WHERE uri=? AND segment=? AND digest=? AND undone=? ORDER BY id "+(redo?"ASC":"DESC")+" LIMIT 1",new String[]{uri,""+part,hash,redo?"1":"0"})){
   if(!c.moveToFirst())throw new IllegalStateException(redo?"Não há alterações para refazer nesta parte.":"Não há alterações para desfazer nesta parte.");
   StudyText from=decode(c.getString(redo?1:3),c.getString(redo?2:4));if(!same(from,expected))throw new IllegalStateException("O histórico já não corresponde a esta versão do caderno.");
   result=decode(c.getString(redo?3:1),c.getString(redo?4:2));writeDraft(db,uri,part,hash,result);ContentValues update=new ContentValues();update.put("undone",redo?0:1);db.update("edit_history",update,"id=?",new String[]{c.getString(0)});
  }db.setTransactionSuccessful();
 }finally{db.endTransaction();}dirty();return result;}
 void restoreSaved(JSONObject row)throws Exception{current();String uri=NotebookBackup.uri(row),hash=row.getString("digest");int part=NotebookBackup.bounded(row,"segment",10000000);if(!hash.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Identidade de texto inválida.");StudyText after=decode(row.getString("value"),row.getString("marks"));SQLiteDatabase db=getWritableDatabase();boolean changed=false;db.beginTransaction();try{StudyText before=null;try(Cursor c=db.rawQuery("SELECT value,marks FROM draft WHERE uri=? AND segment=? AND digest=?",new String[]{uri,""+part,hash})){if(c.moveToFirst())before=decode(c.getString(0),c.getString(1));}if(before==null||!same(before,after)){NotebookBackup.recovery(app,db,"before-part-restore.json");if(before!=null){String bm=marks(before),am=marks(after);long bytes=(long)before.text.getBytes(StandardCharsets.UTF_8).length+bm.getBytes(StandardCharsets.UTF_8).length+after.text.getBytes(StandardCharsets.UTF_8).length+am.getBytes(StandardCharsets.UTF_8).length;if(bytes>4194304)throw new IllegalStateException("Recuperação acima do limite de 4 MB do histórico. O caderno actual foi conservado.");db.delete("edit_history","uri=? AND segment=? AND digest=? AND undone=1",new String[]{uri,""+part,hash});ContentValues v=new ContentValues();v.put("uri",uri);v.put("segment",part);v.put("digest",hash);v.put("before_value",before.text);v.put("before_marks",bm);v.put("after_value",after.text);v.put("after_marks",am);v.put("label","Recuperar cópia anterior");v.put("created",System.currentTimeMillis());db.insertOrThrow("edit_history",null,v);}writeDraft(db,uri,part,hash,after);trimJournal(db,uri,part,hash);changed=true;}db.setTransactionSuccessful();}finally{db.endTransaction();}if(changed)dirty();}
 List<String[]> clips(){List<String[]> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT value,segment,created FROM cut_clip ORDER BY id DESC LIMIT 20",null)){while(c.moveToNext())out.add(new String[]{c.getString(0),c.getString(1),c.getString(2)});}return out;}
 void reset(String uri,int segment,String source){current();getWritableDatabase().delete("draft","uri=? AND segment=? AND digest=?",new String[]{uri,""+segment,digest(source)});dirty();}
 void bookmark(String uri,int segment,int position,String label){current();ContentValues v=new ContentValues();v.put("uri",uri);v.put("segment",segment);v.put("position",position);v.put("label",label);v.put("created",System.currentTimeMillis());getWritableDatabase().insertOrThrow("bookmark",null,v);dirty();}
 List<String[]> bookmarks(String uri){List<String[]> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,segment,position,label FROM bookmark WHERE uri=? ORDER BY created DESC LIMIT 500",new String[]{uri})){while(c.moveToNext())out.add(new String[]{c.getString(0),c.getString(1),c.getString(2),c.getString(3)});}return out;}
 static void relocate(Context context,String oldUri,String newUri){
  if(oldUri.equals(newUri))return;
  try(ReaderStore helper=new ReaderStore(context)){
   SQLiteDatabase db=helper.getWritableDatabase();db.beginTransaction();try{
    // Never discard an existing source draft through INSERT OR IGNORE + DELETE.
    try(Cursor conflict=db.rawQuery("SELECT 1 FROM draft a JOIN draft b ON a.segment=b.segment AND a.digest=b.digest WHERE a.uri=? AND b.uri=? LIMIT 1",new String[]{oldUri,newUri})){
     if(conflict.moveToFirst())throw new IllegalStateException("Já existe um caderno para esta parte no destino. Os dois cadernos e os seus históricos foram conservados nas referências anteriores. Exporte os cadernos antes de resolver o conflito.");
    }
    ContentValues v=new ContentValues();v.put("uri",newUri);
    for(String table:new String[]{"draft","bookmark","edit_history","cut_clip"})db.update(table,v,"uri=?",new String[]{oldUri});
    db.setTransactionSuccessful();
   }finally{db.endTransaction();}
  }
 }
 void removeBookmark(String id){current();getWritableDatabase().delete("bookmark","id=?",new String[]{id});dirty();}
}
